    "Abh\xE4ngige Eintr\xE4ge m\xFCssen ebenfalls entfernt werden.": "\u0C06\u0C27\u0C3E\u0C30\u0C3F\u0C24 \u0C28\u0C2E\u0C4B\u0C26\u0C41\u0C32\u0C28\u0C41 \u0C15\u0C42\u0C21\u0C3E \u0C24\u0C4A\u0C32\u0C17\u0C3F\u0C02\u0C1A\u0C3E\u0C32\u0C3F.",
    Aktiviert: "\u0C2A\u0C4D\u0C30\u0C3E\u0C30\u0C02\u0C2D\u0C3F\u0C02\u0C1A\u0C2C\u0C21\u0C3F\u0C02\u0C26\u0C3F",
    "Alle Bereiche": "\u0C05\u0C28\u0C4D\u0C28\u0C3F \u0C2A\u0C4D\u0C2F\u0C3E\u0C28\u0C46\u0C32\u0C4D\u200C\u0C32\u0C41",
    Atome: "\u0C2A\u0C30\u0C2E\u0C3E\u0C23\u0C41\u0C35\u0C41\u0C32\u0C41",
    Bewegen: "\u0C15\u0C26\u0C3F\u0C32\u0C3F\u0C02\u0C1A\u0C41",
    Bindungen: "\u0C2C\u0C02\u0C27\u0C3E\u0C32\u0C41",
    Darstellung: "\u0C30\u0C42\u0C2A\u0C02",
    "Das Volumen muss gr\xF6\xDFer als Null sein.": "\u0C2A\u0C30\u0C3F\u0C2E\u0C3E\u0C23\u0C02 \u0C38\u0C41\u0C28\u0C4D\u0C28\u0C3E \u0C15\u0C02\u0C1F\u0C47 \u0C0E\u0C15\u0C4D\u0C15\u0C41\u0C35\u0C17\u0C3E \u0C09\u0C02\u0C21\u0C3E\u0C32\u0C3F.",
    Deaktiviert: "\u0C28\u0C3F\u0C32\u0C3F\u0C2A\u0C3F\u0C35\u0C47\u0C2F\u0C2C\u0C21\u0C3F\u0C02\u0C26\u0C3F",
    "Der Elektrode muss ein Material zugewiesen werden!": "\u0C0E\u0C32\u0C15\u0C4D\u0C1F\u0C4D\u0C30\u0C4B\u0C21\u0C4D\u200C\u0C15\u0C41 \u0C2A\u0C26\u0C3E\u0C30\u0C4D\u0C25\u0C3E\u0C28\u0C4D\u0C28\u0C3F \u0C15\u0C47\u0C1F\u0C3E\u0C2F\u0C3F\u0C02\u0C1A\u0C02\u0C21\u0C3F!",
    "Die ausgef\xE4hlten Atome d\xFCrfen nicht die selben sein.": "\u0C0E\u0C02\u0C1A\u0C41\u0C15\u0C41\u0C28\u0C4D\u0C28 \u0C2A\u0C30\u0C2E\u0C3E\u0C23\u0C41\u0C35\u0C41\u0C32\u0C41 \u0C35\u0C47\u0C30\u0C4D\u0C35\u0C47\u0C30\u0C41\u0C17\u0C3E \u0C09\u0C02\u0C21\u0C3E\u0C32\u0C3F.",
    "Doppelklicken zum L\xF6sen der Verbindung.": "\u0C35\u0C3F\u0C21\u0C26\u0C40\u0C2F\u0C21\u0C3E\u0C28\u0C3F\u0C15\u0C3F \u0C30\u0C46\u0C02\u0C21\u0C41\u0C38\u0C3E\u0C30\u0C4D\u0C32\u0C41 \u0C15\u0C4D\u0C32\u0C3F\u0C15\u0C4D \u0C1A\u0C47\u0C2F\u0C02\u0C21\u0C3F.",
    "Ein Elektrodenmaterial muss ein elementarer Stoff aus einem Atom sein.": "\u0C0E\u0C32\u0C15\u0C4D\u0C1F\u0C4D\u0C30\u0C4B\u0C21\u0C4D \u0C2A\u0C26\u0C3E\u0C30\u0C4D\u0C25\u0C02 \u0C12\u0C15\u0C47 \u0C2A\u0C30\u0C2E\u0C3E\u0C23\u0C41\u0C35\u0C41\u0C24\u0C4B \u0C38\u0C42\u0C1A\u0C3F\u0C02\u0C1A\u0C47 \u0C2E\u0C42\u0C32\u0C15\u0C02 \u0C05\u0C2F\u0C3F \u0C09\u0C02\u0C21\u0C3E\u0C32\u0C3F.",
    Elektrolyse: "\u0C35\u0C3F\u0C26\u0C4D\u0C2F\u0C41\u0C26\u0C4D\u0C35\u0C3F\u0C36\u0C4D\u0C32\u0C47\u0C37\u0C23",
    Element: "\u0C2E\u0C42\u0C32\u0C15\u0C02",
    "Es muss ein Volumen angegeben werden.": "\u0C2A\u0C30\u0C3F\u0C2E\u0C3E\u0C23\u0C3E\u0C28\u0C4D\u0C28\u0C3F \u0C28\u0C2E\u0C4B\u0C26\u0C41 \u0C1A\u0C47\u0C2F\u0C02\u0C21\u0C3F.",
    "Es muss eine Bindungsart ausgew\xE4hlt werden.": "\u0C2C\u0C02\u0C27 \u0C30\u0C15\u0C3E\u0C28\u0C4D\u0C28\u0C3F \u0C0E\u0C02\u0C1A\u0C41\u0C15\u0C4B\u0C02\u0C21\u0C3F.",
    "Es wurde kein Atom zum Molek\xFCl hinzugef\xFCgt.": "\u0C05\u0C23\u0C41\u0C35\u0C41\u0C15\u0C41 \u0C0F \u0C2A\u0C30\u0C2E\u0C3E\u0C23\u0C41\u0C35\u0C42 \u0C1C\u0C4B\u0C21\u0C3F\u0C02\u0C1A\u0C2C\u0C21\u0C32\u0C47\u0C26\u0C41.",
    "Es wurde keine/eine falsche Menge angegeben. Der Wert muss eine Zahl ohne Einheit sein.": "\u0C2F\u0C42\u0C28\u0C3F\u0C1F\u0C4D \u0C32\u0C47\u0C28\u0C3F \u0C38\u0C02\u0C16\u0C4D\u0C2F\u0C17\u0C3E \u0C38\u0C30\u0C48\u0C28 \u0C2E\u0C4A\u0C24\u0C4D\u0C24\u0C3E\u0C28\u0C4D\u0C28\u0C3F \u0C28\u0C2E\u0C4B\u0C26\u0C41 \u0C1A\u0C47\u0C2F\u0C02\u0C21\u0C3F.",
    "Es wurden keine Atome f\xFCr eine Bindung ausgew\xE4hlt.": "\u0C2C\u0C02\u0C27\u0C3F\u0C02\u0C1A\u0C3E\u0C32\u0C4D\u0C38\u0C3F\u0C28 \u0C2A\u0C30\u0C2E\u0C3E\u0C23\u0C41\u0C35\u0C41\u0C32\u0C28\u0C41 \u0C0E\u0C02\u0C1A\u0C41\u0C15\u0C4B\u0C02\u0C21\u0C3F.",
    "Experimentelle Molek\xFCldarstellung": "\u0C2A\u0C4D\u0C30\u0C2F\u0C4B\u0C17\u0C3E\u0C24\u0C4D\u0C2E\u0C15 \u0C05\u0C23\u0C41 \u0C1A\u0C3F\u0C24\u0C4D\u0C30\u0C23",
    "Galvanische Zelle": "\u0C17\u0C3E\u0C32\u0C4D\u0C35\u0C3E\u0C28\u0C3F\u0C15\u0C4D \u0C38\u0C46\u0C32\u0C4D",
    Inhalt: "\u0C35\u0C3F\u0C37\u0C2F\u0C35\u0C38\u0C4D\u0C24\u0C41\u0C35\u0C41",
    "Inhalt aus {from} zu {to} transferieren.": "{from} \u0C28\u0C41\u0C02\u0C21\u0C3F {to}\u0C15\u0C3F \u0C35\u0C3F\u0C37\u0C2F\u0C35\u0C38\u0C4D\u0C24\u0C41\u0C35\u0C41\u0C28\u0C41 \u0C2C\u0C26\u0C3F\u0C32\u0C40 \u0C1A\u0C47\u0C2F\u0C02\u0C21\u0C3F.",
    "Inhalt aus {from} zu {to} \xFCberf\xFChrt.": "{from} \u0C28\u0C41\u0C02\u0C21\u0C3F {to}\u0C15\u0C3F \u0C35\u0C3F\u0C37\u0C2F\u0C35\u0C38\u0C4D\u0C24\u0C41\u0C35\u0C41 \u0C2C\u0C26\u0C3F\u0C32\u0C40 \u0C1A\u0C47\u0C2F\u0C2C\u0C21\u0C3F\u0C02\u0C26\u0C3F.",
    "Inhalt und Molek\xFCl": "\u0C35\u0C3F\u0C37\u0C2F\u0C35\u0C38\u0C4D\u0C24\u0C41\u0C35\u0C41 \u0C2E\u0C30\u0C3F\u0C2F\u0C41 \u0C05\u0C23\u0C41\u0C35\u0C41",
