    "Molek\xFCl: Auswahl": "\u0D12\u0D30\u0D41 \u0D24\u0D28\u0D4D\u0D2E\u0D3E\u0D24\u0D4D\u0D30 \u0D24\u0D3F\u0D30\u0D1E\u0D4D\u0D1E\u0D46\u0D1F\u0D41\u0D15\u0D4D\u0D15\u0D41\u0D15",
