    "{from} aus {to} entfernt.": "{from} {to}\u0D7D \u0D28\u0D3F\u0D28\u0D4D\u0D28\u0D4D \u0D28\u0D40\u0D15\u0D4D\u0D15\u0D3F.",
    "{from} in {to} einf\xFCgen.": "{from} {to}\u0D32\u0D47\u0D15\u0D4D\u0D15\u0D4D \u0D07\u0D1F\u0D41\u0D15.",
    "{from} in {to} eingef\xFCgt.": "{from} {to}\u0D32\u0D47\u0D15\u0D4D\u0D15\u0D4D \u0D07\u0D1F\u0D4D\u0D1F\u0D41.",
