    Quellstromst\u00E4rke: "\u0E01\u0E23\u0E30\u0E41\u0E2A\u0E44\u0E1F\u0E1F\u0E49\u0E32\u0E15\u0E49\u0E19\u0E17\u0E32\u0E07",
    "verbundenes Gemisch": "\u0E2A\u0E32\u0E23\u0E1C\u0E2A\u0E21\u0E17\u0E35\u0E48\u0E40\u0E0A\u0E37\u0E48\u0E2D\u0E21\u0E15\u0E48\u0E2D",
    Elektrodenmaterial: "\u0E27\u0E31\u0E2A\u0E14\u0E38\u0E2D\u0E34\u0E40\u0E25\u0E47\u0E01\u0E42\u0E17\u0E23\u0E14",
    entfernen: "\u0E19\u0E33\u0E2D\u0E2D\u0E01",
    speichern: "\u0E1A\u0E31\u0E19\u0E17\u0E36\u0E01",
    "neues Molek\xFCl": "\u0E42\u0E21\u0E40\u0E25\u0E01\u0E38\u0E25\u0E43\u0E2B\u0E21\u0E48",
    "neues Gemisch": "\u0E2A\u0E32\u0E23\u0E1C\u0E2A\u0E21\u0E43\u0E2B\u0E21\u0E48",
    \u00D6ffnen: "\u0E40\u0E1B\u0E34\u0E14",
    Schlie\u00DFen: "\u0E1B\u0E34\u0E14",
    Einschalten: "\u0E40\u0E1B\u0E34\u0E14\u0E2A\u0E27\u0E34\u0E15\u0E0A\u0E4C",
    Ausschalten: "\u0E1B\u0E34\u0E14\u0E2A\u0E27\u0E34\u0E15\u0E0A\u0E4C",
    "Abh\xE4ngige Eintr\xE4ge m\xFCssen ebenfalls entfernt werden.": "\u0E15\u0E49\u0E2D\u0E07\u0E19\u0E33\u0E23\u0E32\u0E22\u0E01\u0E32\u0E23\u0E17\u0E35\u0E48\u0E02\u0E36\u0E49\u0E19\u0E15\u0E48\u0E2D\u0E01\u0E31\u0E19\u0E2D\u0E2D\u0E01\u0E14\u0E49\u0E27\u0E22",
    Aktiviert: "\u0E40\u0E1B\u0E34\u0E14\u0E43\u0E0A\u0E49\u0E07\u0E32\u0E19",
    "Alle Bereiche": "\u0E41\u0E1C\u0E07\u0E17\u0E31\u0E49\u0E07\u0E2B\u0E21\u0E14",
