    "Nur Inhalt": "\u0E40\u0E19\u0E37\u0E49\u0E2D\u0E2B\u0E32\u0E40\u0E17\u0E48\u0E32\u0E19\u0E31\u0E49\u0E19",
    "Panel-Ansicht": "\u0E40\u0E04\u0E49\u0E32\u0E42\u0E04\u0E23\u0E07\u0E41\u0E1C\u0E07",
    "Stoffmenge {symbol} Ionen [mol]": "\u0E1B\u0E23\u0E34\u0E21\u0E32\u0E13\u0E44\u0E2D\u0E2D\u0E2D\u0E19 {symbol} [mol]",
    Stromst\u00E4rke: "\u0E01\u0E23\u0E30\u0E41\u0E2A\u0E44\u0E1F\u0E1F\u0E49\u0E32",
