    Ausschalten: "\u04E8\u0448\u0456\u0440\u0443",
    "Abh\xE4ngige Eintr\xE4ge m\xFCssen ebenfalls entfernt werden.": "\u0422\u04D9\u0443\u0435\u043B\u0434\u0456 \u0436\u0430\u0437\u0431\u0430\u043B\u0430\u0440\u0434\u044B \u0434\u0430 \u0430\u043B\u044B\u043F \u0442\u0430\u0441\u0442\u0430\u0443 \u043A\u0435\u0440\u0435\u043A.",
    Aktiviert: "\u049A\u043E\u0441\u0443\u043B\u044B",
    "Alle Bereiche": "\u0411\u0430\u0440\u043B\u044B\u049B \u043F\u0430\u043D\u0435\u043B\u044C\u0434\u0435\u0440",
