    Ausschalten: "\u04E8\u0447\u04AF\u0440\u04AF\u04AF",
    "Abh\xE4ngige Eintr\xE4ge m\xFCssen ebenfalls entfernt werden.": "\u041A\u04E9\u0437 \u043A\u0430\u0440\u0430\u043D\u0434\u044B \u0436\u0430\u0437\u0443\u0443\u043B\u0430\u0440\u0434\u044B \u0434\u0430 \u0430\u043B\u044B\u043F \u0441\u0430\u043B\u0443\u0443 \u043A\u0435\u0440\u0435\u043A.",
    Aktiviert: "\u0418\u0448\u0442\u0435\u0442\u0438\u043B\u0434\u0438",
    "Alle Bereiche": "\u0411\u0430\u0440\u0434\u044B\u043A \u043F\u0430\u043D\u0435\u043B\u0434\u0435\u0440",
