    "Doppelklicken zum L\xF6sen der Verbindung.": "\u053F\u0561\u057A\u0576 \u0561\u0576\u057B\u0561\u057F\u0565\u056C\u0578\u0582 \u0570\u0561\u0574\u0561\u0580 \u056F\u0580\u056F\u0576\u0561\u056F\u056B \u057D\u0565\u0572\u0574\u0565\u0584\u0589",
    "Ein Elektrodenmaterial muss ein elementarer Stoff aus einem Atom sein.": "\u0537\u056C\u0565\u056F\u057F\u0580\u0578\u0564\u056B \u0576\u0575\u0578\u0582\u0569\u0568 \u057A\u0565\u057F\u0584 \u0567 \u056C\u056B\u0576\u056B \u0574\u0565\u056F \u0561\u057F\u0578\u0574\u0578\u057E \u0576\u0565\u0580\u056F\u0561\u0575\u0561\u0581\u057E\u0578\u0572 \u057F\u0561\u0580\u0580\u0561\u056F\u0561\u0576 \u0576\u0575\u0578\u0582\u0569\u0589",
    Elektrolyse: "\u0537\u056C\u0565\u056F\u057F\u0580\u0578\u056C\u056B\u0566",
    Element: "\u054F\u0561\u0580\u0580",
    "Es muss ein Volumen angegeben werden.": "\u054A\u0565\u057F\u0584 \u0567 \u0576\u0577\u0565\u056C \u056E\u0561\u057E\u0561\u056C\u0568\u0589",
    "Es muss eine Bindungsart ausgew\xE4hlt werden.": "\u054A\u0565\u057F\u0584 \u0567 \u0568\u0576\u057F\u0580\u0565\u056C \u056F\u0561\u057A\u056B \u057F\u0565\u057D\u0561\u056F\u0568\u0589",
    "Es wurde kein Atom zum Molek\xFCl hinzugef\xFCgt.": "\u0544\u0578\u056C\u0565\u056F\u0578\u0582\u056C\u056B\u0576 \u0561\u057F\u0578\u0574 \u0579\u056B \u0561\u057E\u0565\u056C\u0561\u0581\u057E\u0565\u056C\u0589",
    "Es wurde keine/eine falsche Menge angegeben. Der Wert muss eine Zahl ohne Einheit sein.": "\u0554\u0561\u0576\u0561\u056F\u0568 \u0576\u0577\u057E\u0561\u056E \u0579\u0567 \u056F\u0561\u0574 \u057D\u056D\u0561\u056C \u0567\u0589 \u0531\u0580\u056A\u0565\u0584\u0568 \u057A\u0565\u057F\u0584 \u0567 \u056C\u056B\u0576\u056B \u0561\u057C\u0561\u0576\u0581 \u0574\u056B\u0561\u057E\u0578\u0580\u056B \u0569\u056B\u057E\u0589",
    "Es wurden keine Atome f\xFCr eine Bindung ausgew\xE4hlt.": "\u053F\u0561\u057A\u056B \u0570\u0561\u0574\u0561\u0580 \u0561\u057F\u0578\u0574\u0576\u0565\u0580 \u0579\u0565\u0576 \u0568\u0576\u057F\u0580\u057E\u0565\u056C\u0589",
    "Experimentelle Molek\xFCldarstellung": "\u0544\u0578\u056C\u0565\u056F\u0578\u0582\u056C\u056B \u0563\u056E\u0574\u0561\u0576 \u0583\u0578\u0580\u0571\u0576\u0561\u056F\u0561\u0576 \u057F\u0565\u057D\u0584",
    "Galvanische Zelle": "\u0533\u0561\u056C\u057E\u0561\u0576\u0561\u056F\u0561\u0576 \u0562\u057B\u056B\u057B",
