    Quellstromst\u00E4rke: "\u062F\u06D5\u0645\u0627 \u0647\u06D5\u06CC\u06CC \u06CC\u0627 \u0686\u0627\u06A4\u06A9\u0627\u0646\u06CC\u06CE",
    "verbundenes Gemisch": "\u062A\u06D5\u06A4\u0644\u0647\u06D5\u06A4\u06CC\u0627 \u06AF\u0631\u06CE\u062F\u0627\u06CC\u06CC",
    Elektrodenmaterial: "\u0645\u0627\u062A\u06D5\u0631\u06CC\u0627\u0644\u0627 \u0626\u06D5\u0644\u06D5\u06A9\u062A\u0631\u06C6\u062F\u06CE",
    "Uber dieses Men\xFC k\xF6nnen chemische Stoffe und Komponenten erstellt und vorgegeben werden.": "\u06A4\u06CE \u067E\u06CE\u0634\u06D5\u06A9\u06CE \u0628\u06A9\u0627\u0631 \u0628\u06CC\u0646\u0646 \u062F\u0627 \u06A9\u0648 \u0645\u0627\u062F\u06D5\u06CC\u06CE\u0646 \u06A9\u06CC\u0645\u06CC\u0627\u06CC\u06CC \u0626\u0648\u0648 \u067E\u06CE\u06A9\u0647\u0627\u062A\u06D5\u06CC\u0627\u0646 \u0628\u0627\u0641\u0631\u06CC\u0646\u0646 \u0626\u0648\u0648 \u067E\u06CE\u0634\u0633\u0627\u0632 \u0628\u06A9\u0646.",
    "\xDCber dieses Men\xFC k\xF6nnen neue Objekte ausgew\xE4hlt und platziert werden.": "\u06A4\u06CE \u067E\u06CE\u0634\u06D5\u06A9\u06CE \u0628\u06A9\u0627\u0631 \u0628\u06CC\u0646\u0646 \u062F\u0627 \u06A9\u0648 \u062A\u0634\u062A\u06CE\u0646 \u0646\u0648\u0648 \u0647\u0644\u0628\u0698\u06CE\u0631\u0646 \u0626\u0648\u0648 \u0628\u062C\u06CC\u0647 \u0628\u06A9\u0646.",
    entfernen: "\u0631\u0627\u06A9\u0631\u0646",
