    Laborger\u00E4te: "\u06A9\u06D5\u0644\u0648\u067E\u06D5\u0644\u06CC \u062A\u0627\u0642\u06CC\u06AF\u06D5",
    Elektronik: "\u0626\u06D5\u0644\u06CC\u06A9\u062A\u0631\u06C6\u0646\u06CC\u06A9",
    "Panel anzeigen": "\u067E\u0627\u0646\u06CE\u06B5 \u067E\u06CC\u0634\u0627\u0646 \u0628\u062F\u06D5",
    Objekt: "\u0634\u062A",
    "Objekt leeren": "\u0634\u062A \u0628\u06D5\u062A\u0627\u06B5 \u0628\u06A9\u06D5\u0631\u06D5\u0648\u06D5",
