    "Kategorie: Erdalkalimetalle": "\u067E\u06C6\u0644: \u0645\u06CE\u062A\u0627\u06B5\u06D5\u06A9\u0627\u0646\u06CC \u062E\u0627\u06A9\u06CC \u0626\u06D5\u0644\u06A9\u0627\u0644\u06CC",
