    Nichtmetalle: "\u0646\u0627\u0626\u06D5\u0644\u06CC\u06A9\u062A\u0631\u06C6\u0645\u06CE\u062A\u0627\u0644\u06D5\u06A9\u0627\u0646",
    "Kategorie: Edelgase": "\u067E\u06C6\u0644: \u06AF\u0627\u0632\u06D5 \u06AF\u06D5\u0648\u0631\u06D5\u06A9\u0627\u0646",
    Edelgase: "\u06AF\u0627\u0632\u06D5 \u06AF\u06D5\u0648\u0631\u06D5\u06A9\u0627\u0646",
    "Kategorie: Alkalimetalle": "\u067E\u06C6\u0644: \u0645\u06CE\u062A\u0627\u06B5\u06D5 \u0626\u06D5\u0644\u06A9\u0627\u0644\u06CC\u06CC\u06D5\u06A9\u0627\u0646",
