    Quellstromst\u00E4rke: "\u062C\u06D5\u0631\u06CC\u0627\u0646\u06CC \u0633\u06D5\u0631\u0686\u0627\u0648\u06D5",
    "verbundenes Gemisch": "\u062A\u06CE\u06A9\u06D5\u06B5\u06D5\u06CC \u067E\u06D5\u06CC\u0648\u06D5\u0633\u062A\u06A9\u0631\u0627\u0648",
    Elektrodenmaterial: "\u0645\u0627\u062F\u062F\u06D5\u06CC \u0626\u06D5\u0644\u06CC\u06A9\u062A\u0631\u06C6\u062F",
    "Uber dieses Men\xFC k\xF6nnen chemische Stoffe und Komponenten erstellt und vorgegeben werden.": "\u0626\u06D5\u0645 \u0645\u06CE\u0646\u06CC\u0648\u06D5 \u0628\u06D5\u06A9\u0627\u0631\u0628\u0647\u06CE\u0646\u06D5 \u0628\u06C6 \u062F\u0631\u0648\u0633\u062A\u06A9\u0631\u062F\u0646 \u0648 \u067E\u06CE\u0634\u0648\u06D5\u062E\u062A\u06D5 \u062F\u06CC\u0627\u0631\u06CC\u06A9\u0631\u062F\u0646\u06CC \u0645\u0627\u062F\u062F\u06D5 \u0648 \u067E\u06CE\u06A9\u0647\u0627\u062A\u06D5 \u06A9\u06CC\u0645\u06CC\u0627\u06CC\u06CC\u06D5\u06A9\u0627\u0646.",
    "\xDCber dieses Men\xFC k\xF6nnen neue Objekte ausgew\xE4hlt und platziert werden.": "\u0626\u06D5\u0645 \u0645\u06CE\u0646\u06CC\u0648\u06D5 \u0628\u06D5\u06A9\u0627\u0631\u0628\u0647\u06CE\u0646\u06D5 \u0628\u06C6 \u0647\u06D5\u06B5\u0628\u0698\u0627\u0631\u062F\u0646 \u0648 \u062F\u0627\u0646\u0627\u0646\u06CC \u0634\u062A\u06D5 \u0646\u0648\u06CE\u06CC\u06D5\u06A9\u0627\u0646.",
